const input=$json.body??$json;
const evidenceStatus=String(input.evidence_status??input.status??'').toLowerCase();
const dealId=input.deal_id,leadId=input.lead_id,propertyId=input.property_id;
const closingDate=String(input.closing_date??'').trim();
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const requiredEvidence=Array.isArray(input.required_evidence)?input.required_evidence:[];
const verifiedEvidence=Array.isArray(input.verified_evidence)?input.verified_evidence:[];
const failedEvidence=Array.isArray(input.failed_evidence)?input.failed_evidence:[];
const milestones=Array.isArray(input.milestones)?input.milestones:[];
const executionIdentity=String(input.execution_identity??input.executed_by??'').trim();
const executed=Boolean(input.executed_agreement===true||input.agreement_executed===true||String(input.agreement_status??'').toLowerCase()==='executed');
const signed=Boolean(input.signed_evidence===true||input.signature_status&&String(input.signature_status).toLowerCase()==='executed'||String(input.signature_status).toLowerCase()==='signed');
const evidenceComplete=requiredEvidence.length===0||requiredEvidence.every(req=>verifiedEvidence.some(v=>String(v.id??v.type??v).toLowerCase()===String(req.id??req.type??req).toLowerCase()));
const milestonesComplete=milestones.length===0||milestones.every(m=>['completed','verified'].includes(String(m.status??'').toLowerCase()));
let outcome_status='needs_review',next='WF-126',reason='final closing outcome requires review';
if(input.dnc===true){outcome_status='blocked_dnc';reason='DNC/contact restriction';}
else if(blockers.length){outcome_status='blocked';reason='active closing blockers';}
else if(!dealId||!leadId||!propertyId){outcome_status='incomplete_identity';reason='deal/property/lead identity incomplete';}
else if(!closingDate){outcome_status='closing_date_missing';reason='closing date missing';}
else if(evidenceStatus==='evidence_failed'||failedEvidence.length){outcome_status='evidence_failed';next='WF-326';reason='failed closing evidence requires reconciliation';}
else if(!evidenceComplete||evidenceStatus==='evidence_gap'){outcome_status='evidence_incomplete';next='WF-326';reason='required closing evidence is not fully verified';}
else if(!milestonesComplete){outcome_status='completion_incomplete';next='WF-325';reason='closing milestones are not fully completed';}
else if(!executed||!signed){outcome_status='execution_evidence_missing';next='WF-322';reason='executed agreement or signature evidence is missing';}
else if(!executionIdentity){outcome_status='execution_identity_missing';next='WF-126';reason='execution identity is missing';}
else{outcome_status='closing_outcome_ready';next='WF-328';reason='closing evidence, milestones, execution and signature evidence reconcile successfully';}
return [{json:{...input,workflow_id:'WF-327',workflow_name:'Reconciled Closing Evidence → Final Closing Outcome & Completion Controller',outcome_status,reason,deal_id:dealId,lead_id:leadId,property_id:propertyId,closing_date:closingDate||null,evidence_complete:evidenceComplete,milestones_complete:milestonesComplete,executed_agreement:executed,signed_evidence:signed,execution_identity:executionIdentity||null,next_workflow:next,human_review_required:!['closing_outcome_ready','evidence_incomplete','evidence_failed','completion_incomplete'].includes(outcome_status),crm_activity:{activity_type:'final_closing_outcome',deal_id:dealId,lead_id:leadId,property_id:propertyId,status:outcome_status,closing_date:closingDate||null,reason}}}];
